import unittest

import names

class NamesTests(unittest.TestCase):
    def test_strips_surrounding_space(self):
        self.assertEqual(names.normalize_name(" \tAda\n "), "Ada")

    def test_preserves_internal_space(self):
        self.assertEqual(names.normalize_name("Ada  Lovelace"), "Ada  Lovelace")

    def test_rejects_non_string(self):
        for value in (None, 42, True, b"Ada", [], {}):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    names.normalize_name(value)

    def test_empty_and_whitespace_names(self):
        for value in ("", " \t\n", "\u2003"):
            with self.subTest(value=value):
                self.assertEqual(names.normalize_name(value), "")

    def test_normalizes_names_in_order_without_mutation(self):
        values = [" Grace ", "\tAda  Lovelace\n", "", "  ", " Grace "]
        original = values.copy()

        result = names.normalize_names(values)

        self.assertIsInstance(result, list)
        self.assertEqual(result, ["Grace", "Ada  Lovelace", "", "", "Grace"])
        self.assertEqual(values, original)
        self.assertIsNot(result, values)
        result.append("Linus")
        self.assertEqual(values, original)

    def test_empty_list_returns_new_list(self):
        values = []
        result = names.normalize_names(values)
        self.assertEqual(result, [])
        self.assertIsNot(result, values)

    def test_rejects_invalid_collections(self):
        for values in (None, "Ada", b"Ada", ("Ada",), {"Ada"}, {"name": "Ada"}, 42,
                       iter(["Ada"])):
            with self.subTest(values=values):
                with self.assertRaises(TypeError):
                    names.normalize_names(values)

    def test_invalid_item_raises_without_returning_partial_results(self):
        for invalid in (None, 42, True, b"Ada", [], {}):
            for position in range(3):
                values = [" Ada ", " Grace "]
                values.insert(position, invalid)
                original = values.copy()
                with self.subTest(invalid=invalid, position=position):
                    with self.assertRaises(TypeError):
                        names.normalize_names(values)
                    self.assertEqual(values, original)


